<?php

function weekmate_popup_allowed_page_welcome() {
    return is_front_page()
        || is_page('hrms-payroll-software')
        || is_page('taskhub')
        || is_page('crm')
        || is_page('connect')
        || is_page('email-marketing-tool');
}
function weekmate_wm_popup_welcome() {
    if (!weekmate_popup_allowed_page_welcome()) {
        return;
    }
    /* ============================================================
       TESTIMONIALS FROM ACF OPTIONS
       ============================================================ */
    $wm_testi_opt = get_field('testimonials_section_copy', 'option');
    $wm_testimonials = [];
    if (!empty($wm_testi_opt) && !empty($wm_testi_opt['testimonials_repeater']) && is_array($wm_testi_opt['testimonials_repeater'])) {
      foreach ($wm_testi_opt['testimonials_repeater'] as $wm_t) {
          $wm_q = trim(wp_strip_all_tags($wm_t['content'] ?? ''));
          if ($wm_q === '') {
              continue;
          }
          $wm_name = trim(wp_strip_all_tags($wm_t['client_name'] ?? ''));
          $wm_role = trim(wp_strip_all_tags($wm_t['designation'] ?? ''));
          $wm_image = $wm_t['client_image'] ?? '';
          $wm_image_url = '';
          if (is_array($wm_image)) {
              $wm_image_url = $wm_image['url'] ?? '';

          } elseif (is_numeric($wm_image)) {
              $wm_image_url = wp_get_attachment_image_url(
                  (int) $wm_image,
                  'thumbnail'
              );

          } elseif (is_string($wm_image)) {
              $wm_image_url = $wm_image;
          }
          $wm_testimonials[] = [
              'quote' => $wm_q,
              'name'  => $wm_name,
              'role'  => $wm_role,
              'image' => esc_url_raw($wm_image_url),
          ];
      }
    }
?>
<script>
    window.WM_POPUP_DATA = <?php
    echo wp_json_encode(
        [
            'testimonials' => $wm_testimonials
        ],
        JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
    );
    ?>;
</script>
<!-- WeekMate welcome pop-up (opens 4s after page load) | testimonials from ACF: <?php echo count($wm_testimonials); ?> -->
